VAR_INPUT n : INT; END_VAR VAR_OUTPUT q : INT; END_VAR
CASE n OF
  1, 3: q := 1;
  4..9: q := 2;
  -1: q := 9;
ELSE q := 0;
END_CASE;

VAR i : INT; j : INT; END_VAR
WHILE i < 5 DO i := i + 1; END_WHILE;
REPEAT j := j + 1; UNTIL j >= 5 END_REPEAT;

VAR i : INT; n : INT; END_VAR
FOR i := 1 TO 10 DO
  IF i = 3 THEN CONTINUE; END_IF;
  IF i = 8 THEN EXIT; END_IF;
  n := n + 1;
END_FOR;
RETURN;

FUNCTION Double : INT
VAR_INPUT x : INT; END_VAR
Double := x * 2;
END_FUNCTION

VAR r : INT; END_VAR
r := Double(21);

VAR eyes : ARRAY [1..4] OF BOOL; delay : ARRAY [1..4] OF TON; jam : ARRAY [1..4] OF BOOL; i : INT; END_VAR
FOR i := 1 TO 4 DO
  delay[i](IN := eyes[i], PT := T#3s);
  jam[i] := delay[i].Q;
END_FOR;

TYPE Merge : STRUCT gap : TON; count : CTU; END_STRUCT; END_TYPE
VAR m : Merge; eye : BOOL; open : BOOL; END_VAR
m.gap(IN := NOT eye, PT := T#500ms);
m.count(CU := eye, PV := 100);
open := m.gap.Q;

TYPE Pkg : STRUCT id : DINT; dest : INT; END_STRUCT; END_TYPE
VAR a : Pkg; b : Pkg; track : ARRAY [0..3] OF Pkg; i : INT; END_VAR
b := a;
FOR i := 3 TO 1 BY -1 DO track[i] := track[i - 1]; END_FOR;

TYPE Pkg : STRUCT id : DINT; END_STRUCT; END_TYPE
FUNCTION Make : Pkg
VAR_INPUT id : DINT; END_VAR
Make.id := id;
END_FUNCTION

FUNCTION_BLOCK Latch
VAR_INPUT p : Pkg; END_VAR
VAR_OUTPUT held : Pkg; END_VAR
held := p;
END_FUNCTION_BLOCK

VAR l : Latch; box : Pkg; copy : Pkg; n : DINT; END_VAR
box := Make(7);
l(p := box, held => copy);
n := l.held.id;

FUNCTION Span : INT
VAR_INPUT lo : INT; hi : INT; END_VAR
Span := hi - lo;
END_FUNCTION

VAR n : INT; END_VAR
n := Span(hi := 10, lo := 3);

VAR Ax : AXIS_REF; pwr : MC_Power; mv : MC_MoveAbsolute; END_VAR
pwr(Axis := Ax, Enable := TRUE);
mv(Axis := Ax, Execute := pwr.Status, Position := 10, Velocity := 20, Acceleration := 100, Deceleration := 100);

VAR x : INT := 50; n : INT; s : STRING := 'conveyor'; t : STRING; END_VAR
n := LIMIT(MN := 0, IN := x, MX := 10);
t := MID(IN := s, L := 3, P := 2);

FUNCTION Scale : INT
VAR_INPUT v : INT; gain : INT := 2; END_VAR
Scale := v * gain;
END_FUNCTION

VAR n : INT; END_VAR
n := Scale(v := 21);

TYPE Mode : (Idle, Running); END_TYPE
VAR m : Mode := Mode#Idle; END_VAR
IF m = Mode#Idle THEN m := Mode#Running; END_IF;

VAR_GLOBAL Shared : INT := 5; END_VAR
VAR n : INT; END_VAR
n := Shared;

VAR_GLOBAL t : TON; END_VAR
VAR q : BOOL; END_VAR
t(IN := TRUE, PT := T#1s);
q := t.Q;

TYPE Inner : STRUCT a : INT; END_STRUCT; END_TYPE
TYPE Outer : STRUCT
  inner : Inner;
  data : ARRAY [1..3] OF INT;
END_STRUCT; END_TYPE
VAR p : Outer; n : INT; END_VAR
n := p.inner.a + p.data[2];

TYPE Mode : (Idle, Running := 10, Fault); END_TYPE
VAR m : Mode := Running; n : INT; END_VAR
CASE m OF
  Idle: n := 0;
  Running: n := 1;
  Fault: n := 2;
END_CASE;

TYPE Percent : INT (0..100); END_TYPE
VAR p : Percent := 50; END_VAR
p := 60;

VAR
  si : SINT; i : INT; di : DINT;
  usi : USINT; ui : UINT; udi : UDINT;
  b : BYTE; w : WORD; dw : DWORD;
END_VAR
i := i + 1;
ui := ui + 1;
w := w AND 16#00FF;

VAR t : TIME := T#1m30s; u : TIME; n : DINT; END_VAR
u := t + T#500ms;
n := TIME_TO_DINT(u);

VAR d : DATE := D#2024-02-29; t : TOD := TOD#08:00:00; x : DT; gap : TIME; END_VAR
x := CONCAT_DATE_TOD(d, t) + T#90m;
gap := x - DT#2024-02-29-00:00:00;

VAR a : TIME := T#1s; b : TIME; t : TOD := TOD#12:00:00; END_VAR
b := ADD_TIME(a, T#500ms);
t := ADD_TOD_TIME(t, MULTIME(b, 2));

VAR s : STRING[20] := 'line$N'; n : INT; END_VAR
s := CONCAT(s, 'more');
n := LEN(s);

VAR
  a : STRING := 'abc';
  b : STRING := 'abd';
  lo : STRING; q : BOOL;
END_VAR
q := a < b;
lo := MIN(a, b);

VAR
  h : WORD := 16#FF;
  bits : BYTE := 2#1010_1010;
  oct : INT := 8#17;
  typed : INT := INT#5;
  r : REAL := 1.0E-3;
END_VAR
h := h OR WORD#16#0F;

VAR
  t : TON; f : TOF; p : TP;
  r : R_TRIG; ft : F_TRIG;
  cu : CTU; cd : CTD; ud : CTUD;
  s : SR; rs : RS;
END_VAR
t(IN := TRUE, PT := T#1s);
cu(CU := t.Q, PV := 10);

VAR i : INT := 7; r : REAL; w : WORD; s : STRING; END_VAR
r := INT_TO_REAL(i);
w := INT_TO_WORD(i);
s := INT_TO_STRING(i);
i := STRING_TO_INT('42');

VAR
  a : INT := 3; b : INT := 2; c : INT := 1;
  q : BOOL; n : INT;
END_VAR
q := GT(a, b, c);
n := ADD(a, b, c);

VAR s : STRING := 'hello world'; part : STRING; at : INT; END_VAR
part := MID(s, 5, 1);
at := FIND(s, 'world');
part := REPLACE(s, 'X', 1, 1);

VAR_GLOBAL Shared : INT; END_VAR
VAR_EXTERNAL Shared : INT; END_VAR
Shared := 1;

VAR
  Eye AT %IX100.0 : BOOL;
  Run AT %QX100.0 : BOOL;
  Count AT %IW2 : INT;
END_VAR
Run := NOT Eye;

VAR
  Count AT %MW0 : INT;
  Total AT %MD1 : DINT;
  Flag AT %MX8.0 : BOOL;
END_VAR
Count := Count + 1;
Flag := Count > 3;

PROGRAM Main
VAR n : INT; END_VAR
n := n + 1;
END_PROGRAM

CONFIGURATION Cfg
  RESOURCE Res ON PLC
    TASK Fast(INTERVAL := T#10ms, PRIORITY := 1);
    TASK Slow(INTERVAL := T#100ms, PRIORITY := 2);
    PROGRAM A WITH Fast : Main;
    PROGRAM B WITH Slow : Main;
  END_RESOURCE
END_CONFIGURATION

PROGRAM Main
VAR n : INT; END_VAR
n := n + 1;
END_PROGRAM

CONFIGURATION Cfg
  RESOURCE Res ON PLC
    TASK Fast(INTERVAL := T#10ms, PRIORITY := 1);
    PROGRAM A WITH Fast : Main;
    PROGRAM Always : Main;
  END_RESOURCE
END_CONFIGURATION

VAR n : INT; END_VAR
n := n + 1;

CONFIGURATION Cfg
  RESOURCE Res ON PLC
    TASK Fast(INTERVAL := T#10ms, PRIORITY := 1);
    PROGRAM Main WITH Fast;
  END_RESOURCE
END_CONFIGURATION

PROGRAM Main
VAR n : INT; END_VAR
n := 1;
END_PROGRAM

CONFIGURATION Cfg
  RESOURCE A ON PLC
    TASK T1(INTERVAL := T#10ms, PRIORITY := 1);
    PROGRAM P1 WITH T1 : Main;
  END_RESOURCE
  RESOURCE B ON PLC
    TASK T2(INTERVAL := T#10ms, PRIORITY := 1);
    PROGRAM P2 WITH T2 : Main;
  END_RESOURCE
END_CONFIGURATION

TYPE Row : ARRAY [1..3] OF INT; END_TYPE
VAR a : Row; b : Row := [1, 2, 3]; END_VAR
a := b;

VAR CONSTANT ZONES : INT := 4; END_VAR
VAR eyes : ARRAY [0..ZONES - 1] OF BOOL; END_VAR
eyes[ZONES - 1] := TRUE;

TYPE Pkg : STRUCT id : DINT; dest : INT; END_STRUCT; END_TYPE
VAR p : Pkg := (id := 7, dest := 3); lane : ARRAY [1..2] OF Pkg := [(id := 1), (id := 2)]; END_VAR
p.dest := 4;

FUNCTION_BLOCK Acc
VAR n : INT; END_VAR
METHOD Put : INT
  VAR_INPUT v : INT; END_VAR
  n := n + v;
  Put := n;
END_METHOD
END_FUNCTION_BLOCK

VAR a : Acc; r1 : INT; END_VAR
r1 := a.Put(v := 3) + a.Put(4);

TYPE Pkg : STRUCT id : INT; END_STRUCT; END_TYPE
VAR zones : ARRAY [1..3] OF Pkg; z : REF_TO Pkg; z2 : REF_TO Pkg; ok : BOOL; END_VAR
z := REF(zones[2]);
z^.id := 9;
z2 := z;
ok := z2 <> NULL;

VAR n : INT; END_VAR
n := 1
n := 2;

TYPE Pt : STRUCT a : INT; b : REAL; END_STRUCT; END_TYPE
VAR p : Pt; END_VAR
p := 0;

TYPE Mode : (Idle, Run) END_TYPE

VAR m : Mode := Mode.Run; n : INT; END_VAR
CASE m OF
  Mode.Idle: n := 0;
  Mode.Run: n := 1;
END_CASE;

TYPE Axis :
STRUCT
  Speed : REAL := 1.5;
  Mode : INT := 2;
END_STRUCT
END_TYPE

VAR a : Axis; b : Axis := (Speed := 3.0); s : REAL; END_VAR
s := a.Speed + b.Speed;

VAR_INPUT Eye : BOOL; Button : BOOL; Clear : BOOL; END_VAR
VAR_OUTPUT Jam : BOOL; END_VAR
LADDER
  |Eye| |P Button| (S Jam);
  |Clear| (R Jam);
END_LADDER

VAR_INPUT Skip : BOOL; Halt : BOOL; A : BOOL; END_VAR
VAR_OUTPUT B : BOOL; C : BOOL; END_VAR
LADDER
  |Skip| >>Done;
  |A| (B);
  Done: |A| (C);
  |Halt| RETURN;
END_LADDER

VAR A : BOOL; B : BOOL; END_VAR
LADDER
  Top: |A| (B);
  |B| >>Top;
END_LADDER
